function run_q6_aoe_subject001_all()
% Q6 AOE subject001 specification, estimation, contrast and figures.
sid='subject001';repo=fileparts(fileparts(fileparts(mfilename('fullpath'))));glm='C:\aliceproject\GLM';fl=fullfile(glm,'first_level');d=fullfile(fl,'nirs_spm_inputs_v2_fulltimeline_trial1',sid);nf=fullfile(d,[sid '_nirs_data.mat']);root=fullfile(repo,'results','q6_extraneous_aoe','cohort_specification',sid);if ~isfolder(root),mkdir(root);end;addpath(fl);addpath(fullfile(glm,'toolboxes','spm'));addpath(genpath(fullfile(glm,'toolboxes','NIRS_SPM_v4_r1')));ev=readtable(fullfile(d,[sid '_events_used_v2.csv']),'TextType','string');ev.condition=string(ev.condition);src=["ApplicationOfEndoloopsLILE","ApplicationOfEndoloopsHILE","ApplicationOfEndoloopsLIHE","ApplicationOfEndoloopsHIHE"];sel=sortrows(ev(ismember(ev.condition,src),:),'onset_sec');assert(all(ismember(src,unique(sel.condition))));on=cell(1,4);du=cell(1,4);for i=1:4,ix=sel.condition==src(i);assert(sum(ix)==1);on{i}=double(sel.onset_sec(ix))';du{i}=double(sel.duration_sec(ix))';end;names=cellstr(src);writetable(sel,fullfile(root,[sid '_q6_aoe_events_used.csv']));save(fullfile(root,[sid '_q6_aoe_multiple_conditions.mat']),'names','on','du','-v7');
for h=["hbo","hbr"],if h=="hbo",hb="HbO";else,hb="HbR";end;hr=fullfile(root,char(hb));if ~isfolder(hr),mkdir(hr);end;A=specification_batch(nf,char(h),'DCT, 128','none',0,hr,0,0,1,names,on,du);X=full(A.xX.X);rn=string(A.xX.name(:));ic=contains(lower(rn),'constant');assert(size(X,2)==5&&sum(ic)==1);tx=X(:,~ic);Z=(tx-mean(tx))./std(tx,0,1);R=corrcoef(Z);mr=max(abs(R(~eye(4))));v=zeros(4,1);for j=1:4,y=tx(:,j);z=[ones(size(X,1),1),tx(:,setdiff(1:4,j))];r2=1-sum((y-z*(z\y)).^2)/sum((y-mean(y)).^2);v(j)=1/max(1-r2,eps);end;assert(rank(X)==5&&mr<.95&&max(v)<=10);writematrix(X,fullfile(hr,[sid '_' char(hb) '_q6_aoe_convolved_design.csv']));writetable(table((1:numel(rn))',rn,ic,'VariableNames',{'column_index','regressor','is_constant'}),fullfile(hr,[sid '_' char(hb) '_q6_aoe_regressor_table.csv']));writetable(table(rn(~ic),v,'VariableNames',{'regressor','vif'}),fullfile(hr,[sid '_' char(hb) '_q6_aoe_vif.csv']));end
for hb=["HbO","HbR"],sf=fullfile(root,char(hb),sprintf('SPM_indiv_%s.mat',hb));nirs_spm_estimation_batch_fixed(sf,nf);L=load(sf,'SPM_nirs');S=L.SPM_nirs;B=double(S.nirs.beta);assert(isequal(size(B),[5 61]));N=string(S.xX.name(:));k=zeros(4,1);for i=1:4,k(i)=find(contains(N,src(i)),1);end;c=zeros(5,1);c(k)=[-.5 -.5 .5 .5];rss=double(S.nirs.ResSS);if ~isvector(rss),rss=diag(rss)';end;df=double(S.xX.erdf);b=c'*B;se=sqrt(max((c'*double(S.xX.Bcov)*c).*(rss/df),0));t=b./se;p=betainc(df./(df+t.^2),df/2,.5);q=bh(p);M=readtable(fullfile(fl,'nirs_spm_inputs',sid,[sid '_channel_metadata.csv']),'TextType','string');T=table(repmat(string(sid),61,1),repmat(hb,61,1),(1:61)',string(M.channel_id),string(M.channel_type),string(M.roi),string(M.laterality),b(:),se(:),t(:),p(:),q(:),repmat(join(string(c'),' '),61,1),'VariableNames',{'subject_id','hemoglobin','channel_index','channel_id','channel_type','roi','laterality','contrast_beta','contrast_se','contrast_t','contrast_p_two_sided','contrast_q_bh61','contrast_vector'});writetable(T,fullfile(root,sprintf('subject001_%s_q6_high_extraneous_minus_low_extraneous_aoe_channel_contrasts.csv',hb)));writetable(table(hb,61,sum(p<.05),sum(q<.05),mean(b),median(b),'VariableNames',{'hemoglobin','n_channels','n_p_lt_005','n_q_bh61_lt_005','mean_contrast_beta','median_contrast_beta'}),fullfile(root,sprintf('subject001_%s_q6_aoe_contrast_summary.csv',hb)));
field='dxyData';if hb=="HbO",field='oxyData';end;data=load(nf,'nirs_data');y=double(data.nirs_data.(field)(:,1));yf=spm_filter_HPF_LPF_WMDL(S.xX.K,y);Xf=full(S.xX.xKXs.X);fit=Xf*B(:,1);res=yf-fit;tsec=(0:size(X,1)-1)'*double(S.xY.RT);figdir=fullfile(root,char(hb),'figures');if ~isfolder(figdir),mkdir(figdir);end;h=(0:size(S.xBF.bf,1)-1)'*double(S.xBF.dt);f=figure('Visible','off','Color','w');plot(h,S.xBF.bf(:,1),'Color',[0 0.35 0.7],'LineWidth',1.8);grid on;xlabel('Time after event onset (s)');ylabel('HRF amplitude');title(sprintf('Q6 AOE canonical HRF (%s)',hb),'Color','k');exportgraphics(f,fullfile(figdir,sprintf('%s_%s_q6_aoe_canonical_hrf.png',sid,hb)),'Resolution',220);close(f);f=figure('Visible','off','Color','w');imagesc(X(:,~ic)');axis tight;colormap(f,parula);colorbar;yticks(1:4);yticklabels(N(~ic));xlabel('Scan');ylabel('HRF-convolved task regressor');title(sprintf('%s Q6 AOE regressor heatmap (%s)',sid,hb),'Color','k');exportgraphics(f,fullfile(figdir,sprintf('%s_%s_q6_aoe_convolved_regressor_heatmap.png',sid,hb)),'Resolution',220);close(f);f=figure('Visible','off','Color','w');plot(tsec,X(:,~ic),'LineWidth',1.1);grid on;xlabel('Time (s)');ylabel('Task regressor');title(sprintf('%s Q6 AOE four convolved regressors (%s)',sid,hb),'Color','k');legend(N(~ic),'Location','eastoutside');exportgraphics(f,fullfile(figdir,sprintf('%s_%s_q6_aoe_convolved_regressor_timeseries.png',sid,hb)),'Resolution',220);close(f);f=figure('Visible','off','Color','w');tiledlayout(3,1);nexttile;plot(tsec,yf);hold on;plot(tsec,fit,'LineWidth',1.2);grid on;title(sprintf('%s channel 1 %s: observed and fitted signal',sid,hb));legend('Observed','GLM fitted');nexttile;plot(tsec,res);hold on;yline(0,'--k');grid on;title('GLM residual');nexttile;plot(tsec,X(:,~ic));grid on;title('Q6 AOE HRF-convolved regressors');legend(N(~ic),'Location','eastoutside');exportgraphics(f,fullfile(figdir,sprintf('%s_channel01_%s_q6_aoe_fit.png',sid,hb)),'Resolution',220);close(f);end
end
function q=bh(p),q=nan(size(p));v=isfinite(p);pv=p(v);[s,o]=sort(pv(:));m=numel(s);z=min(1,flipud(cummin(flipud(s.*m./(1:m)'))));zv=zeros(size(pv));zv(o)=z;q(v)=zv;end
